    // Mapping:
    //   C[i][j]   -> C_param(j, i)
    //   A[j][k]   -> A_param(k, j)
    //   B[i][k]   -> B_param(k, i)
    //   B[j][k]   -> B_param(k, j)
    //   A[i][k]   -> A_param(k, i)

