#include "syr2k.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Simple tunables for this kernel. Adjusting these can help match a
// specific machine’s cache and core topology without touching the
// Halide scheduling logic.
static constexpr int kTileI = 64;  // strip size along the i (row) dimension

/**
 * Initialize arrays A, B, C and scalars alpha, beta.
 * This mirrors the original C init_array() function, but uses small,
 * scheduled Halide pipelines for better locality and vectorization.
 */
static void init_array(int n, int m,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // Original C code:
    //
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < m; j++) {
    //     A[i][j] = ((i*j+1)%n) / n;
    //     B[i][j] = ((i*j+2)%m) / m;
    //   }
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+3)%n) / m;
    //
    // Mapping C[i][j] -> Buffer(j, i),
    // A[i][j] (n x m) -> Buffer(j, i) with shape (m, n),
    // B[i][j] similarly.

    Func init_A("init_A"), init_B("init_B"), init_C("init_C");

    // A has shape (m, n), accessed as A(j, i) == A[i][j]
    init_A(j, i) = cast<num_t>(((i * j + 1) % n)) / cast<int>(n);

    // B has shape (m, n), accessed as B(j, i) == B[i][j]
    init_B(j, i) = cast<num_t>(((i * j + 2) % m)) / cast<int>(m);

    // C has shape (n, n), accessed as C(j, i) == C[i][j]
    init_C(j, i) = cast<num_t>(((i * j + 3) % n)) / cast<int>(m);

    // Simple but effective schedule for initialization:
    //  - j is the innermost (unit-stride) dimension -> vectorize over j
    //  - parallelize over i to use all cores
    Target t = get_jit_target_from_environment();
    int vec = t.natural_vector_size(type_of<num_t>());
    if (vec <= 0) vec = 1;

    init_A
        .bound(i, 0, n).bound(j, 0, m)
        .reorder(j, i)
        .vectorize(j, vec)
        .parallel(i);
    init_B
        .bound(i, 0, n).bound(j, 0, m)
        .reorder(j, i)
        .vectorize(j, vec)
        .parallel(i);
    init_C
        .bound(i, 0, n).bound(j, 0, n)
        .reorder(j, i)
        .vectorize(j, vec)
        .parallel(i);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers
    // Original arrays:
    //   C[n][n], A[n][m], B[n][m]
    // We map C[i][j] -> C(j, i) with shape (n, n)
    // A[i][j] (n x m) -> A(j, i) with shape (m, n)
    // B[i][j] (n x m) -> B(j, i) with shape (m, n)
    Buffer<num_t, 2> C(n, n);
    Buffer<num_t, 2> A(m, n);
    Buffer<num_t, 2> B(m, n);

    // ImageParams to feed buffers into Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(n, m, &alpha, &beta, C, A, B);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Vars and reduction domain
    Var i("i"), j("j");
    // A.dim(0) == m, so RDom over 'k' corresponds to the "K" dimension in BLAS
    RDom k(0, A.dim(0).extent(), "k");

    // Halide implementation of kernel_syr2k:
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++)
    //     for (j = 0; j <= i; j++) {
    //       C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k];
    //     }
    // }
    //
    // We compute for all (i,j) in [0..n-1]x[0..n-1], but apply the update
    // only when j <= i. For j > i, C[i][j] remains as initialized.
    //
    // Mapping:
    //   C[i][j]   -> C_param(j, i)
    //   A[j][k]   -> A_param(k, j)
    //   B[i][k]   -> B_param(k, i)
    //   B[j][k]   -> B_param(k, j)
    //   A[i][k]   -> A_param(k, i)

    Func syr2k("syr2k");

    Expr alpha_e = Expr(alpha);
    Expr beta_e  = Expr(beta);

    // Initial multiplication by beta for j <= i; otherwise keep original C.
    // This is a pure definition (no self-dependence).
    syr2k(j, i) = select(j <= i,
                         beta_e * C_param(j, i),
                         C_param(j, i));

    // Rank-2k update, only for j <= i:
    //   C[i][j] += alpha * (A[j][k] * B[i][k] + B[j][k] * A[i][k]);
    //
    // We explicitly hoist A(i,k) and B(i,k) out of the j-expression to make
    // it easier for Halide to reuse them across the inner j-loop.
    Expr Aik = A_param(k, i);
    Expr Bik = B_param(k, i);

    syr2k(j, i) += select(
        j <= i,
        alpha_e * (A_param(k, j) * Bik +
                   B_param(k, j) * Aik),
        cast<num_t>(0));

    // ------------------------------------------------------------------
    // Schedule
    // ------------------------------------------------------------------
    //
    // Goal:
    //  - Keep j as the innermost (contiguous) dimension to get unit-stride
    //    access in C and allow vectorization.
    //  - Parallelize across i-strips to use all CPU cores.
    //  - Strip-mine i into tiles of height kTileI to improve cache locality.
    //
    // Note: we *never* parallelize or vectorize across the reduction
    // variable 'k', which avoids any race conditions.
    Target target = get_jit_target_from_environment();
    int vec = target.natural_vector_size(type_of<num_t>());
    if (vec <= 0) vec = 1;

    // Bound the iteration space explicitly (helps the compiler and
    // avoids accidental dynamic extents in schedules).
    syr2k
        .bound(i, 0, n)
        .bound(j, 0, n);

    // Split i into an outer strip-index (io) and an inner index (ii).
    Var io("io"), ii("ii");

    // Pure definition schedule:
    //  - tiles along i
    //  - for each tile, j is inner and vectorized
    //  - tiles (io) are processed in parallel
    syr2k
        .split(i, io, ii, kTileI)
        .reorder(j, ii, io)  // j innermost, then ii, then io
        .vectorize(j, vec)
        .parallel(io);

    // Update definition schedule:
    //  We mirror the tiling of i, and keep j innermost so that
    //  we can vectorize across j for the reduction as well.
    syr2k.update()
        .split(i, io, ii, kTileI)
        // Order from innermost to outermost: j, k, ii, io.
        // This gives loops: for io (parallel) { for ii { for k { for j (vector) { ... }}}}
        .reorder(j, k, ii, io)
        .vectorize(j, vec)
        .parallel(io);

    // JIT-compile the kernel for the selected target
    syr2k.compile_jit(target);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    syr2k.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (mainly to prevent dead-code elimination
    // and to allow correctness checking if desired).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Recall: C(ii,jj) in C maps to C(jj,ii) in Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
